import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {runInNewContext} from 'node:vm';

const read=path=>readFileSync(new URL('../'+path,import.meta.url),'utf8');
const js=read('script.js'),html=read('index.php'),side=read('studio-next.js');
const css=read('studio-next.css'),sw=read('sw.js');
const labels=[...side.matchAll(/^add\('([^']+)','([^']+)'/gm)].map(m=>m[2]);
assert.deepEqual(labels,['Поиск','Моя волна','Плейлисты','Мне нравится','Офлайн','Подборки','Настройки']);
assert.match(html,/data-theme="rainbow"/);
assert.match(html,/id="rainbow-speed-input"/);
assert.match(html,/oninput="setRainbowSpeed\(this.value\)"/);
assert.match(css,/\.theme-choice-rainbow/);
assert.match(css,/rainbow-speed-control\[hidden\]/);
assert.match(js,/function setRainbowSpeed\(value\)/);
assert.match(js,/startRainbowCycle\(\)/);
assert.match(js,/setInterval\(\(\)=>applyRainbowFrame\(\),180\)/);
assert.match(js,/document\.hidden/);
assert.match(js,/rainbow:\{main:/);
const start=js.indexOf('function rainbowRgb(');
const end=js.indexOf('\nfunction applyRainbowFrame(',start);
assert.ok(start>0&&end>start,'Rainbow colour conversion exists');
const palette={Math,Number};
runInNewContext(js.slice(start,end)+'\nglobalThis.convert=rainbowRgb',palette);
for(const hue of [0,60,120,180,240,300]){
    const rgb=palette.convert(hue);
    assert.equal(rgb.length,3);
    for(const n of rgb)assert.ok(n>=0&&n<=255);
}
const reasonStart=js.indexOf('function offlineCacheReason(');
const reasonEnd=js.indexOf('\nfunction rememberOfflineStoredTrack(',reasonStart);
assert.ok(reasonStart>0&&reasonEnd>reasonStart,'Cache retention policy exists');
const reason={};
runInNewContext(js.slice(reasonStart,reasonEnd)+'\nglobalThis.resolveReason=offlineCacheReason',reason);
assert.equal(reason.resolveReason('playlist','manual'),'manual');
assert.equal(reason.resolveReason('completed','playlist'),'completed');
assert.equal(reason.resolveReason('manual','completed'),'manual');
const cacheStart=js.indexOf('async function cacheTrackSilently(');
const cacheEnd=js.indexOf('\nasync function getDeviceCachedAudio(',cacheStart);
assert.ok(cacheStart>0&&cacheEnd>cacheStart);
const cache=js.slice(cacheStart,cacheEnd);
assert.match(cache,/options\.reason !== 'completed'/);
assert.doesNotMatch(cache,/isUrlStillInAnyPlaylist/);
assert.match(js,/cacheTrackSilently\(finishedTrack, \{ reason: 'completed'/);
assert.match(js,/rememberOfflineStoredTrack\(job\.track\)/);
assert.match(js,/enqueueNativeTrackCache\(track,'manual',true\)/);
assert.match(js,/enqueueWebTrackCache\(track,'manual',true\)/);
assert.match(js,/window\.downloadTrackFile = function\(index\)/);
assert.match(js,/window\.downloadTrack = function\(index\)/);
assert.match(js,/if\(cached\?\.inCache\)ready\.push\(track\)/);
assert.match(js,/getDeviceCachedAudio\(track\)/);
assert.match(js,/const blob = await response\.blob\(\)/);
assert.match(js,/await cache\.put\(cacheUrl, new Response\(blob/);
assert.match(js,/if\(!force && \(entry\?\.reason==='manual'\|\|entry\?\.reason==='completed'\)\)return false/);
assert.match(sw,/dagstudio-player-shell-v2346/);
console.log('RAINBOW_SPEED_SEARCH_AND_OFFLINE_COMPLETE_MANUAL_RETENTION_OK');
